// Create a new client instance
const client = new Client({
  intents: [GatewayIntentBits.Guilds],
  partials: ['MESSAGE', 'CHANNEL', 'REACTION'], // Optional, only include the partials you need
});

// Listener for the ready event, the bot is ready to start receiving messages
client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}!`);
});

// Ban command handler
client.on('interactionCreate', async interaction => {
  if (!interaction.isChatInputCommand() || interaction.commandName !== 'ban') return;

  // Extract the arguments for the ban command
  const { member, options: { string: reason }, guild } = interaction;

  if (!member || !guild || !reason.banker) {
    interaction.editReply("Something went wrong. Please try again.");
    return;
  }

  try {
    // Invoke the Ban method on the guild member
    await guild.members.ban(member.user, { reason });
    interaction.editReply(`Successfully banned ${member.user.tag}.\nReason: ${reason}`);
  } catch (error) {
    interaction.editReply(`Failed to ban ${member.user.tag}. Error: ${error}`);
  }
});

// Connect to the Discord API
client.login('YOUR-BOT-TOKEN'); // Replace with your own bot token 
