Here's how you can create and apply a first-person controller script in Godot Engine 4.x in GDScript:

1. Create a new KinematicBody node and call it "Player". In Godot 4.x, KinematicBody replaces the functionality of the old "RigidBody2D" and "RigidBody" nodes, and KinematicBody can now simulate physics on all axes.
2. In the "Player" node, add scripts to the "Script" and "State Machine" tabs, and write the following "first_person_controller.gd" script:
```gdscript
extends KinematicBody

enum CameraState {MAIN, INVENTORY}

export var main_acceleration = 7
export var max_speed = 15
export var gravity = -30
export var no_gravity_jump_speed = 10
export var gravity_jump_speed = 18

enum MovementDir {UP, DOWN, LEFT, RIGHT}

export(NodePath) var camera_animation
var camera_animation_ref:String setget set_camera_animation_ref

func _ready():
	set_default_camera_animation(true)

func _physics_process(delta):
	# Handle camera rotation based on input
	if Input.is_action_pressed("rotate_left"):
		look_at(Vector3(-sin(rotation.y), 0, cos(rotation.y)))
	if Input.is_action_pressed("rotate_right"):
		look_at(Vector3(sin(rotation.y), 0, -cos(rotation.y)))

	# Handle movement
	var movement = Vector3()

	# Accelerate forward
	if Input.is_action_pressed("move_forward"):
		movement -= transform.basis.z
	if Input.is_action_pressed("move_backward"):
		movement += transform.basis.z

	# Accelerate sideways
	if Input.is_action_pressed("move_left"):
		movement -= transform.basis.x
	if Input.is_action_pressed("move_right"):
		movement += transform.basis.x

	# De-accelerate to zero when not pressing one of the movement keys
	var target_speed = movement.normalized() * max_speed * delta
	var new_speed = new_speed.lerp(target_speed, main_acceleration * delta)

	movement = new_speed

	# Gravity
	movement.y += gravity * delta

	if !is_on_floor():
		# Gravity without collision
		if Input.is_action_pressed("move_up"):
			movement.y = no_gravity_jump_speed
			collision_layer = 0
		elif Input.is_action_just_released("move_up"):
			collision_layer = 1
	else:
		# Jump
		if Input.is_action_just_pressed("move_up"):
			collision_layer = 0
			movement.y = gravity_jump_speed
		elif Input.is_action_just_released("move_up"):
			collision_layer = 1

	# Apply movement
	movement = move_and_slide(movement, Vector3.UP)

func _input(event):
	if event.is_action_pressed("toggle_camera") and event.control:
		toggle_camera_state()
	elif event.is_pressed() and event.is_action("rotate_right") or event.is_pressed() and event.is_action("rotate_left"):
		return
	elif event.is_action_pressed("toggle_camera") and not event.control:
		godot_key_events.emit_signal("toggle_editor")

func set_default_camera_animation(is_starting_scene:bool):
	if camera_animation is AnimationNodeStateMachinePlayback:
		camera_animation_ref = ""
		return
	if camera_animation is AnimationPlayer and not is_starting_scene:
		self.camera_animation_ref = camera_animation.get_tree_hiearchy_node().get_path()
	else:
		self.camera_animation_ref = ""
	if is_starting_scene:
		var animations_dir = get_script().get_path().get_base_dir().get_csv_filenames("animations","json")
		for anim_dir in animations_dir:
			var anim_node = load("res://" + anim_dir + "PlayerCameraAnimation.tscn")
			var anim_node_instance = anim_node.instance()
			$"Player".add_child(anim_node_instance)
			$"Player".get_node(anim_node_instance.name).state_machine_node = camera_animation
			$"Player".get_node(anim_node_instance.name).state_machine_node.state_transitions.queue = [
				{id: "camera_active", method: "animate_camera", transition_id: "camera_waiting"},
				{id: "camera_waiting", method: "show_camera", transition_id: "camera_active"},
			]
		if !camera_animation:
